        ct += c == '\n';
    rewind(dict);


    words = alloca(ct * sizeof words);
    drows = alloca(ct * sizeof drows);

    for (i = 0; fscanf(dict, "%s%n", tmp, &len) != EOF; ++i) {

        strcpy(words[i] = alloca(len), tmp);


        strcpy(drows[i] = alloca(len), tmp);
