int main(void)
{
	printf("Nim Game\n\n");

	int Tokens = 12;

	while(Tokens > 0)
	{
		printf("How many tokens would you like to take?: ");

		int uin;
		scanf("%i", &uin);

		int nextTokens = playerTurn(Tokens, uin);

		if (nextTokens == Tokens)
