	c.y = r*sin(theta);

	return c;
}

vector addVector(vector a,vector b){
	vector c;

	c.x = a.x + b.x;
	c.y = a.y + b.y;

	return c;
}

vector subtractVector(vector a,vector b){
	vector c;

	c.x = a.x - b.x;
	c.y = a.y - b.y;

	return c;
}

vector multiplyVector(vector a,double b){
	vector c;

	c.x = b*a.x;
	c.y = b*a.y;

	return c;
}

vector divideVector(vector a,double b){
	vector c;

	c.x = a.x/b;
	c.y = a.y/b;

	return c;
}

