#include <stdio.h>


unsigned int divisor_sum(unsigned int n) {
    unsigned int total = 1, power = 2;
    unsigned int p;

    for (; (n & 1) == 0; power <<= 1, n >>= 1) {
        total += power;
    }

    for (p = 3; p * p <= n; p += 2) {
        unsigned int sum = 1;
        for (power = p; n % p == 0; power *= p, n /= p) {
            sum += power;
        }
        total *= sum;
    }

    if (n > 1) {
        total *= n + 1;
    }
    return total;
}

