int digit_set(int n) {
    static const int powers[] = {
        1, 10, 100, 1000, 10000, 100000, 1000000, 10000000,
        100000000, 1000000000
    };

    int dset;
    for (dset = 0; n; n /= 10)
        dset += powers[n % 10];
    return dset;
}


