    for (; (n & 1) == 0; n >>= 1) {
        ++total;
    }

    for (unsigned int p = 3; p * p <= n; p += 2) {
        unsigned int count = 1;
        for (; n % p == 0; n /= p) {
            ++count;
        }
        total *= count;
    }

    if (n > 1) {
        total *= 2;
    }
    return total;
}

