#include <stdio.h>

unsigned int divisor_count(unsigned int n) {
    unsigned int total = 1;
    unsigned int p;


    for (; (n & 1) == 0; n >>= 1) {
        ++total;
    }

    for (p = 3; p * p <= n; p += 2) {
        unsigned int count = 1;
        for (; n % p == 0; n /= p) {
            ++count;
        }
        total *= count;
    }

    if (n > 1) {
        total *= 2;
    }
    return total;
}

