void iSeed(char *seed, int flag)
{
	register ub4 i,m;
	for (i=0; i<256; i++) mm[i]=0;
	m = strlen(seed);
	for (i=0; i<256; i++)
	{

        if (i>m) randrsl[i]=0;  else randrsl[i] = seed[i];
	}

	randinit(flag);
}



#define MAXMSG 4096
#define MOD 95
#define START 32

enum ciphermode {
	mEncipher, mDecipher, mNone 
};



char v[MAXMSG];
char* Vernam(char *msg)
	{
		register ub4 i,l;
		l = strlen(msg);

		memset(v,'\0',l+1);

		for (i=0; i<l; i++) 
			v[i] = iRandA() ^ msg[i];
		return v;
	}



char Caesar(enum ciphermode m, char ch, char shift, char modulo, char start)
	{
		register int n;
		if (m == mDecipher) shift = -shift;
		n = (ch-start) + shift;
		n = n % modulo;
		if (n<0) n += modulo;
		return start+n;
	}


char c[MAXMSG];
char* CaesarStr(enum ciphermode m, char *msg, char modulo, char start)
	{
		register ub4 i,l;
		l = strlen(msg);

		memset(c,'\0',l+1);

		for (i=0; i<l; i++) 
			c[i] = Caesar(m, msg[i], iRandA(), modulo, start);
		return c;
	}


