#define pi M_PI

typedef struct{
	double x,y;
}vector;

vector initVector(double r,double theta){
	vector c;

	c.x = r*cos(theta);
	c.y = r*sin(theta);

	return c;
}

vector addVector(vector a,vector b){
	vector c;

	c.x = a.x + b.x;
	c.y = a.y + b.y;

	return c;
}

vector subtractVector(vector a,vector b){
	vector c;

	c.x = a.x - b.x;
	c.y = a.y - b.y;

	return c;
