char results[7];
bool next_result() {
    char *ptr = results + 5;
    int num = 0;
    size_t i;


    if (strcmp(results, "222222") == 0) {
        return false;
    }


    for (i = 0; results[i] != 0; i++) {
        int d = results[i] - '0';
        num = 3 * num + d;
    }


    num++;


    while (num > 0) {
        int rem = num % 3;
        num /= 3;
