typedef struct elem{
	int data;
	struct elem* next;
}cell;

typedef cell* list;

list addToList(list a,int num){

	list iter, temp;
	int i=0;

	if(a==NULL){
		a = (list)malloc(sizeof(cell));
		a->data = num;
		a->next = NULL;
	}
	else{
		iter = a;

		while(iter->next!=NULL){
			iter = iter->next;
		}

		temp = (list)malloc(sizeof(cell));
		temp->data = num;
		temp->next = NULL;

		iter->next = temp;
	}	
	return a;
}

list deleteFromList(list a,int pos){

	int i=1;
	list temp,iter;

	if(a!=NULL){
		iter = a;

		if(pos==1){
			a = a->next;
			iter->next = NULL;
			free(iter);
		}

		else{
			while(i++!=pos-1)
				iter = iter->next;
			temp = iter->next;
			iter->next = temp->next;
			temp->next = NULL;
			free(temp);
		}
	}
	return a;
}

void printList(list a){
	list temp = a;

	printf("List contains following elements : \n");

	while(temp!=NULL){
		printf("%d ",temp->data);
		temp = temp->next;
	}
}

