unsigned long long bruteForceProperDivisorSum(unsigned long long n){
	unsigned long long i,sum = 0;

	for(i=1;i<(n+1)/2;i++)
		if(n%i==0 && n!=i)
			sum += i;

	return sum;
}

void printSeries(unsigned long long* arr,int size,char* type){
