int divisorCount(int n) {
    int i, j, count = 0, k = !(n%2) ? 1 : 2;
    for (i = 1; i*i <= n; i += k) {
        if (!(n%i)) {
            ++count;
            j = n/i;
            if (j != i) ++count;
        }
    }
    return count;
}

