int main(){
	int sum = 0, i, j;
	int try_max = 0;

	int   count_list[3] = {1,0,0};
	for(i=2; i <= 20000; i++){

		try_max = i/2;

		sum = 1;
		for(j=2; j<try_max; j++){

			if (i % j)
				continue; 

			try_max = i/j;

			sum += j;
			if (j != try_max)
				sum += try_max;
		}

		if (sum < i){
			count_list[de]++;
			continue;
		}
