    if(a[i]) return 0;

    v = 0;
    for(i = j - 2; i >= 0; i -= 2) {
        k = 2 * s[i];
        v += k > 9 ? k - 9 : k;
    }

    for(i = j - 1; i >= 0; i -= 2) {
        v += s[i];
    }

    return v % 10 == 0;
}

