    for(i=length;i>1;i--)
    {

        max_num_pos=0;
        for(a=0;a<i;a++)
        {
            if(list[a]>list[max_num_pos])
                max_num_pos=a;
        }

        if(max_num_pos==i-1)

            continue;



        if(max_num_pos)
        {
            moves++;
            do_flip(list, length, max_num_pos+1);
        }



